{
  "name": "MI6960 光功率计",
  "name_en": "MI6960 Optical Power Meter",
  "manufacturer": "",
  "description": "MI6960 光功率计用于实验室中测量激光或其他光源的输出功率。它支持自动校准与归零，并可设置校准因子、偏置、线性修正、平均次数和参考值等测量参数。",
  "description_en": "The MI6960 optical power meter is used in laboratories to measure the output power of lasers or other light sources. It supports automatic calibration and zeroing, and allows configuration of measurement parameters such as calibration factor, offset, linearity correction, averaging, and reference level.",
  "actions": [
    {
      "action_name": "auto-calibrate",
      "description": "执行自动校准和自动归零。",
      "description_en": "Perform automatic calibration and auto-zero."
    },
    {
      "action_name": "auto-settings",
      "description": "获取当前测量设置。",
      "description_en": "Get the current measurement settings."
    },
    {
      "action_name": "auto-calfactor",
      "description": "获取或设置校准因子。",
      "description_en": "Get or set the calibration factor."
    },
    {
      "action_name": "auto-offset",
      "description": "获取或设置测量偏置。",
      "description_en": "Get or set the measurement offset."
    },
    {
      "action_name": "auto-linearityfactor",
      "description": "获取或设置线性修正因子。",
      "description_en": "Get or set the linearity correction factor."
    },
    {
      "action_name": "auto-averages",
      "description": "获取或设置平均次数。",
      "description_en": "Get or set the averaging count."
    },
    {
      "action_name": "auto-reference",
      "description": "获取或设置参考值。",
      "description_en": "Get or set the reference level."
    },
    {
      "action_name": "auto-power",
      "description": "读取当前功率。",
      "description_en": "Read the current power."
    }
  ],
  "tag_hints": [
    "optical power measurement",
    "laser power meter",
    "auto calibration",
    "measurement averaging",
    "reference power",
    "calibration factor",
    "linearity correction"
  ]
}

